"""Software preview of a vanilla JSON model generated by voxelize_vehicle.py.

Renders front / side / isometric views with simple face shading to one PNG so
geometry + palette can be sanity-checked before any server loop.
Usage: python tools/voxel_preview.py <out_model_dir>/base.json <palette.png> <preview.png>
"""

import json
import math
import sys
import zipfile
from PIL import Image, ImageDraw

SHADE = {"up": 1.0, "down": 0.5, "north": 0.8, "south": 0.8, "east": 0.6, "west": 0.6}


def patch(y, x, val, buf, depth):
    """Depth-tested pixel write into a 2D buffer."""
    if 0 <= y < len(buf) and 0 <= x < len(buf[0]) and (buf[y][x] is None or depth < buf[y][x][1]):
        buf[y][x] = (val, depth)


def render(model, palette_png, view="iso", scale=6, keep=None):
    # palette color per uv rect -> rgb
    pal = Image.open(palette_png).convert("RGBA")
    elements = model["elements"]
    used = {}

    def color_for(face):
        u0, v0, u1, v1 = face["uv"]
        key = (round(u0, 3), round(v0, 3), round(u1, 3), round(v1, 3))
        if key not in used:
            px = int(((key[0] + key[2]) / 2) / 16 * pal.width)
            py = int(((key[1] + key[3]) / 2) / 16 * pal.height)
            c = pal.getpixel((min(px, pal.width - 1), min(py, pal.height - 1)))
            used[key] = c
        return used[key]

    polys = []
    for e in elements:
        x0, y0, z0 = e["from"]
        x1, y1, z1 = e["to"]
        corners = {
            name: verts for name, verts in {
                "up": [(x0, y1, z0), (x1, y1, z0), (x1, y1, z1), (x0, y1, z1)],
                "down": [(x0, y0, z0), (x1, y0, z0), (x1, y0, z1), (x0, y0, z1)],
                "north": [(x0, y0, z0), (x1, y0, z0), (x1, y1, z0), (x0, y1, z0)],
                "south": [(x0, y0, z1), (x1, y0, z1), (x1, y1, z1), (x0, y1, z1)],
                "east": [(x1, y0, z0), (x1, y0, z1), (x1, y1, z1), (x1, y1, z0)],
                "west": [(x0, y0, z0), (x0, y0, z1), (x0, y1, z1), (x0, y1, z0)],
            }.items()
        }
        for name, face in e["faces"].items():
            if keep and name not in keep:
                continue
            c = color_for(face)
            sh = SHADE[name]
            col = (int(c[0] * sh), int(c[1] * sh), int(c[2] * sh))
            polys.append((corners[name], col))

    def project(p):
        x, y, z = p
        if view == "front":
            return x, -y, z, None
        if view == "side":
            return z, -y, x, None
        wx = (x - z) * 0.866
        wy = -y + (x + z) * 0.5
        depth = x + z - y * 2.0
        return wx, wy, depth, None

    # rasterize via painter-with-depth per pixel
    tris = []
    for verts, col in polys:
        pr = [project(v)[:3] for v in verts]
        for tri in ((pr[0], pr[1], pr[2]), (pr[0], pr[2], pr[3])):
            tris.append((tri, col))
    allpts = [p for tri, _ in tris for p in tri]
    minx = min(p[0] for p in allpts); maxx = max(p[0] for p in allpts)
    miny = min(p[1] for p in allpts); maxy = max(p[1] for p in allpts)
    W = int((maxx - minx) * scale) + 8
    H = int((maxy - miny) * scale) + 8
    buf = [[None] * W for _ in range(H)]
    for tri, col in tris:
        ts = [((p[0] - minx) * scale + 4, (p[1] - miny) * scale + 4, p[2]) for p in tri]
        bx0 = max(0, int(min(t[0] for t in ts))); bx1 = min(W - 1, int(max(t[0] for t in ts)) + 1)
        by0 = max(0, int(min(t[1] for t in ts))); by1 = min(H - 1, int(max(t[1] for t in ts)) + 1)
        (ax, ay, ad), (bx, by, bd), (cx, cy, cd) = ts
        den = (by - cy) * (ax - cx) + (cx - bx) * (ay - cy)
        if abs(den) < 1e-9:
            continue
        for py in range(by0, by1 + 1):
            for px2 in range(bx0, bx1 + 1):
                w0 = ((by - cy) * (px2 - cx) + (cx - bx) * (py - cy)) / den
                w1 = ((cy - ay) * (px2 - cx) + (ax - cx) * (py - cy)) / den
                w2 = 1 - w0 - w1
                if w0 < -0.02 or w1 < -0.02 or w2 < -0.02:
                    continue
                patch(int(py), int(px2), col, buf, w0 * ad + w1 * bd + w2 * cd)
    img = Image.new("RGB", (W, H), (108, 108, 122))
    px = img.load()
    for yy in range(H):
        for xx in range(W):
            if buf[yy][xx]:
                px[xx, yy] = buf[yy][xx][0]
    return img


def main(model_path, palette_path, out_path):
    model = json.load(open(model_path))
    views = [render(model, palette_path, "front", 6, {"south"}),
             render(model, palette_path, "side", 6, {"east"}),
             render(model, palette_path, "iso", 6, {"up", "east", "south"})]
    w = sum(v.width for v in views) + 16
    h = max(v.height for v in views)
    canvas = Image.new("RGB", (w, h), (30, 30, 34))
    x = 0
    for v in views:
        canvas.paste(v, (x, 0))
        x += v.width + 8
    canvas.save(out_path)
    print(f"preview saved: {out_path} ({canvas.width}x{canvas.height})")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2], sys.argv[3])
